import{_ as s,o as i,c as a,a2 as e}from"./chunks/framework.DnrXFDHb.js";const k=JSON.parse('{"title":"timing — 时间与调度","description":"Tempo、MusicalTime、PlaybackScheduler 的完整说明","frontmatter":{"title":"timing — 时间与调度","description":"Tempo、MusicalTime、PlaybackScheduler 的完整说明"},"headers":[],"relativePath":"architecture/domain/timing.md","filePath":"architecture/domain/timing.md","lastUpdated":1773326634000}'),n={name:"architecture/domain/timing.md"};function d(h,t,p,l,c,o){return i(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="timing-—-时间与调度" tabindex="-1">timing — 时间与调度 <a class="header-anchor" href="#timing-—-时间与调度" aria-label="Permalink to &quot;timing — 时间与调度&quot;">​</a></h1><p><strong>源文件</strong>：<code>src/streammuse/domain/timing/</code></p><p>本模块提供实时音乐系统的所有时间相关抽象：速度（BPM）换算、音乐时间位置表示，以及线程安全的事件调度器。</p><hr><h2 id="tempo" tabindex="-1"><code>Tempo</code> <a class="header-anchor" href="#tempo" aria-label="Permalink to &quot;`Tempo`&quot;">​</a></h2><p><strong>源文件</strong>：<code>timing/tempo.py</code></p><p>不可变的速度配置，作为系统的核心时间基准。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">@dataclass</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">frozen</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Tempo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    bpm: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">float</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ticks_per_beat: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    beats_per_bar: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span></span></code></pre></div><h3 id="字段" tabindex="-1">字段 <a class="header-anchor" href="#字段" aria-label="Permalink to &quot;字段&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>bpm</code></td><td><code>float</code></td><td>每分钟拍数（Beats Per Minute），必须 &gt; 0</td></tr><tr><td><code>ticks_per_beat</code></td><td><code>int</code></td><td>每拍包含的 tick 数，必须 &gt; 0（默认为 4）</td></tr><tr><td><code>beats_per_bar</code></td><td><code>int</code></td><td>每小节拍数，必须 &gt; 0（默认为 4，即 4/4 拍）</td></tr></tbody></table><h3 id="属性与方法" tabindex="-1">属性与方法 <a class="header-anchor" href="#属性与方法" aria-label="Permalink to &quot;属性与方法&quot;">​</a></h3><h4 id="seconds-per-tick-property" tabindex="-1"><code>seconds_per_tick</code> （property） <a class="header-anchor" href="#seconds-per-tick-property" aria-label="Permalink to &quot;`seconds_per_tick` （property）&quot;">​</a></h4><p>单个 tick 对应的实时时长（秒）。</p><p>$$\\text{seconds_per_tick} = \\frac{60.0}{\\text{bpm} \\times \\text{ticks_per_beat}}$$</p><h4 id="ticks-per-bar-property" tabindex="-1"><code>ticks_per_bar</code> （property） <a class="header-anchor" href="#ticks-per-bar-property" aria-label="Permalink to &quot;`ticks_per_bar` （property）&quot;">​</a></h4><p>每小节的总 tick 数：</p><p>$$\\text{ticks_per_bar} = \\text{ticks_per_beat} \\times \\text{beats_per_bar}$$</p><h4 id="tick-to-seconds-tick-float" tabindex="-1"><code>tick_to_seconds(tick) -&gt; float</code> <a class="header-anchor" href="#tick-to-seconds-tick-float" aria-label="Permalink to &quot;`tick_to_seconds(tick) -&gt; float`&quot;">​</a></h4><p>将绝对 tick 转换为实时秒数：</p><p>$$\\text{seconds} = \\text{tick} \\times \\text{seconds_per_tick}$$</p><h4 id="seconds-to-tick-seconds-int" tabindex="-1"><code>seconds_to_tick(seconds) -&gt; int</code> <a class="header-anchor" href="#seconds-to-tick-seconds-int" aria-label="Permalink to &quot;`seconds_to_tick(seconds) -&gt; int`&quot;">​</a></h4><p>将实时秒数转换为 tick（截断为整数）：</p><p>$$\\text{tick} = \\lfloor \\frac{\\text{seconds}}{\\text{seconds_per_tick}} \\rfloor$$</p><hr><h2 id="musicaltime" tabindex="-1"><code>MusicalTime</code> <a class="header-anchor" href="#musicaltime" aria-label="Permalink to &quot;`MusicalTime`&quot;">​</a></h2><p><strong>源文件</strong>：<code>timing/tempo.py</code></p><p>音乐时间位置表示，用于显示「第几小节第几拍」和 metronome（节拍器）回调。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">@dataclass</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">frozen</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">True</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MusicalTime</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    tick: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    bar: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    beat: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    tick_in_beat: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span></span></code></pre></div><h3 id="字段-1" tabindex="-1">字段 <a class="header-anchor" href="#字段-1" aria-label="Permalink to &quot;字段&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>tick</code></td><td><code>int</code></td><td>原始绝对 tick</td></tr><tr><td><code>bar</code></td><td><code>int</code></td><td>小节编号（从 0 开始）</td></tr><tr><td><code>beat</code></td><td><code>int</code></td><td>小节内的拍编号（从 0 开始）</td></tr><tr><td><code>tick_in_beat</code></td><td><code>int</code></td><td>拍内的 tick 偏移（从 0 开始）</td></tr></tbody></table><h3 id="类方法" tabindex="-1">类方法 <a class="header-anchor" href="#类方法" aria-label="Permalink to &quot;类方法&quot;">​</a></h3><h4 id="from-tick-tick-tempo-musicaltime" tabindex="-1"><code>from_tick(tick, tempo) -&gt; MusicalTime</code> <a class="header-anchor" href="#from-tick-tick-tempo-musicaltime" aria-label="Permalink to &quot;`from_tick(tick, tempo) -&gt; MusicalTime`&quot;">​</a></h4><p>从绝对 tick 和 <code>Tempo</code> 计算音乐时间位置。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">@</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">classmethod</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> from_tick</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(cls, tick: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, tempo: Tempo) -&gt; MusicalTime:</span></span></code></pre></div><p>计算公式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ticks_per_bar = tempo.ticks_per_beat * tempo.beats_per_bar</span></span>\n<span class="line"><span>bar           = tick // ticks_per_bar</span></span>\n<span class="line"><span>tick_in_bar   = tick % ticks_per_bar</span></span>\n<span class="line"><span>beat          = tick_in_bar // tempo.ticks_per_beat</span></span>\n<span class="line"><span>tick_in_beat  = tick_in_bar % tempo.ticks_per_beat</span></span></code></pre></div><p><strong>示例</strong>（<code>ticks_per_beat=4</code>, <code>beats_per_bar=4</code>）：</p><table tabindex="0"><thead><tr><th>tick</th><th>bar</th><th>beat</th><th>tick_in_beat</th></tr></thead><tbody><tr><td>0</td><td>0</td><td>0</td><td>0</td></tr><tr><td>4</td><td>0</td><td>1</td><td>0</td></tr><tr><td>16</td><td>1</td><td>0</td><td>0</td></tr><tr><td>19</td><td>1</td><td>0</td><td>3</td></tr></tbody></table><hr><h2 id="playbackscheduler" tabindex="-1"><code>PlaybackScheduler</code> <a class="header-anchor" href="#playbackscheduler" aria-label="Permalink to &quot;`PlaybackScheduler`&quot;">​</a></h2><p><strong>源文件</strong>：<code>timing/scheduler.py</code></p><p>线程安全的音乐事件调度器，按 tick 管理待播放事件队列，并支持取消过时事件（如推理响应替换旧的 model 输出）。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> PlaybackScheduler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    def</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> __init__</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(self) -&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span></span></code></pre></div><p>内部维护 <code>Dict[int, List[MusicalEvent]]</code>（tick → 事件列表）以及一个 <code>threading.Lock</code>，所有方法均在锁保护下运行。</p><h3 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h3><h4 id="schedule-event-tick-none" tabindex="-1"><code>schedule(event, tick) -&gt; None</code> <a class="header-anchor" href="#schedule-event-tick-none" aria-label="Permalink to &quot;`schedule(event, tick) -&gt; None`&quot;">​</a></h4><p>将事件安排在指定 tick 播放。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> schedule</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(self, event: MusicalEvent, tick: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) -&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><p>若该 tick 尚无事件，自动初始化列表。</p><h4 id="get-events-at-tick-tick-list-musicalevent" tabindex="-1"><code>get_events_at_tick(tick) -&gt; List[MusicalEvent]</code> <a class="header-anchor" href="#get-events-at-tick-tick-list-musicalevent" aria-label="Permalink to &quot;`get_events_at_tick(tick) -&gt; List[MusicalEvent]`&quot;">​</a></h4><p>取出并删除指定 tick 上的所有事件。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> get_events_at_tick</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(self, tick: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) -&gt; List[MusicalEvent]:</span></span></code></pre></div><ul><li>若该 tick 无事件，返回空列表</li><li>调用后该 tick 的事件从调度器中移除（consume 语义）</li></ul><h4 id="clear-future-events-from-tick-source-none-none" tabindex="-1"><code>clear_future_events(from_tick, source=None) -&gt; None</code> <a class="header-anchor" href="#clear-future-events-from-tick-source-none-none" aria-label="Permalink to &quot;`clear_future_events(from_tick, source=None) -&gt; None`&quot;">​</a></h4><p>删除从 <code>from_tick</code> 起（含）的所有未来事件。</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">def</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> clear_future_events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    self,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    from_tick: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    source: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">str</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> None</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) -&gt; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">None</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span></code></pre></div><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>from_tick</code></td><td>起始 tick（含），清除该 tick 及之后的事件</td></tr><tr><td><code>source</code></td><td>若指定（如 <code>&quot;model&quot;</code>），只清除该 source 的事件；<code>None</code> 表示清除所有</td></tr></tbody></table><p><strong>典型用途</strong>：收到新的推理响应时，先调用 <code>clear_future_events(generation_start_tick, source=&quot;model&quot;)</code> 清除旧的 model 事件，再调度新事件，避免新旧 model 输出混放。</p>',58)])])}const g=s(n,[["render",d]]);export{k as __pageData,g as default};
